r3rewards3]]},["rlt_dr3roomsee01"]={["arg1"]=[[房间属性设置]],["arg2"]=[[fb18_86]],["arg3"]=[[可见]],["id"]=[[rlt_dr3roomsee01]]},["rlt_dr3story01"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL季彰：平日里师伯的一饮一食诸多讲究，能成功给师伯的茶水下毒，必熟人所为，此事不宜声张，需寻个合适的场地召集弟子询问。;YEL江文鹤：大哥！谁人害我大哥？！传令下去，即刻封住大会出口，其余双鹤弟子随我到舍身崖会集！;YEL杨风：少侠，我等前去舍身崖会集，大会出口暂时被封锁，若有不周之处，望海涵。]],["arg3"]=[[2;2;2]],["id"]=[[rlt_dr3story01]]},["rlt_dr3story02"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL江文鹤：呃啊……你，你为何灭我双鹤庄？;YEL天枢：与邪教为伍，该诛。]],["arg3"]=[[1.5;1.5]],["id"]=[[rlt_dr3story02]]},["rlt_dr3story03"]={["arg1"]=[[副本故事]],["arg2"]=[[天枢虚晃一招，你抬臂上挡，岂料他杀招竟是冲江文鹤而去，一击毙命。;YEL天枢：收起你泛滥的仁慈，敌人可不会对你善良。;余音未了，天枢与星面者已飘然离开。]],["arg3"]=[[2;2;2]],["id"]=[[rlt_dr3story03]]},["rlt_dr3story04"]={["arg1"]=[[副本故事]],["arg2"]=[[你摇晃华山松，从茂密的枝丫间跃下一人。;YEL樊晗：你管我为何在这。]],["arg3"]=[[1.5;1.5]],["id"]=[[rlt_dr3story04]]},["rlt_dr3story05"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL林夫人：可笑啊，我恨他曾将我捧如珍珠，又弃如鱼目，恨他日日夜夜在梦里与那贱人欢好，可等我终于杀了他，我仍不得解脱。;YEL林夫人：你若见了江文鹤，劳你替我传话，就说悦儿有愧，此生是我负了他。]],["arg3"]=[[1.5;1.5]],["id"]=[[rlt_dr3story05]]},["rlt_dr3story06"]={["arg1"]=[[副本故事]],["id"]=[[rlt_dr3story06]]},["rlt_dr3text01"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL叶轻语：双鹤庄正在镇岳宫办传刀大会，邀请了不少武林豪杰捧场，咱们现在过去瞧瞧。]],["id"]=[[rlt_dr3text01]]},["rlt_dr3text02"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL双鹤弟子：呃……我师兄定会教训你。]],["id"]=[[rlt_dr3text02]]},["rlt_dr3text03"]={["arg1"]=[[文本输出]],["arg2"]=[[行吟老者竟唱出双鹤庄前后两任庄主，年少爱慕同一女子的桃色传闻。]],["id"]=[[rlt_dr3text03]]},["rlt_dr3text04"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL大汉：江文鹤庄主多年不成婚，莫不是还惦记着嫂子林夫人。]],["id"]=[[rlt_dr3text04]]},["rlt_dr3text05"]={["arg1"]=[[文本输出]],["arg2"]=[[话一落，听客们发笑，突然来人喝道——]],["id"]=[[rlt_dr3text05]]},["rlt_dr3text06"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL樊晗：谁人编排我师娘，留下舌头！]],["id"]=[[rlt_dr3text06]]},["rlt_dr3text07"]={["arg1"]=[[文本输出]],["arg2"]=[[众人见势不对心虚地逃远，唯刚说话的大汉被樊晗挡住。]],["id"]=[[rlt_dr3text07]]},["rlt_dr3text08"]={["arg1"]=[[文本输出]],["arg2"]=[[樊晗面露不甘和羞恼之色，转身咬牙离开，双鹤弟子紧随其后。]],["id"]=[[rlt_dr3text08]]},["rlt_dr3text09"]={["arg1"]=[[文本输出]],["arg2"]=[[镇岳宫内，鼓声如雷，满堂人或坐或站，皆看向擂台不断叫好。]],["id"]=[[rlt_dr3text09]]},["rlt_dr3text10"]={["arg1"]=[[文本输出]],["arg2"]=[[台上季彰手持一柄弯月轻刀，劈、砍、横、切、斩、扫、斜，招招扣住这七字精髓，舞的赫赫生风，将对手接连攻下擂台。]],["id"]=[[rlt_dr3text10]]},["rlt_dr3text11"]={["arg1"]=[[文本输出]],["arg2"]=[[江文鹤与林夫人在交耳低声谈话，你犹豫着要不要出声打断，江文鹤似有所感，叱问：谁在那？！]],["id"]=[[rlt_dr3text11]]},["rlt_dr3text12"]={["arg1"]=[[文本输出]],["arg2"]=[[林夫人摇了摇头，心事重重地离去。]],["id"]=[[rlt_dr3text12]]},["rlt_dr3text13"]={["arg1"]=[[文本输出]],["arg2"]=[[“陈兄，我决意入梦与潇儿相聚，曾经我只追求最快最绝的刀法，直至潇儿病逝，痛失吾爱，已觉人生了无乐趣，即便梦为虚幻，我亦愿长梦不醒，此信为证，若得陈兄成全，双鹤庄愿受你驱使。”
信为复件，末尾落笔林豪鹤，日期竟是六年前。]],["id"]=[[rlt_dr3text13]]},["rlt_dr3text14"]={["arg1"]=[[文本输出]],["arg2"]=[[你从床板的夹层中抽出一封信。]],["id"]=[[rlt_dr3text14]]},["rlt_dr3text15"]={["arg1"]=[[文本输出]],["arg2"]=[[你右手运力下按，床板瞬间朝外翻转，你掉进一个密室。]],["id"]=[[rlt_dr3text15]]},["rlt_dr3text16"]={["arg1"]=[[文本输出]],["arg2"]=[[画上女子双目脉脉含情，让人看着有些脸红心跳，旁边题字云：“相逢情便深，恨不相逢早。识尽千千万万人，终不似、伊家好。林豪鹤留。”]],["id"]=[[rlt_dr3text16]]},["rlt_dr3text17"]={["arg1"]=[[文本输出]],["arg2"]=[[书案上堆满林豪鹤写给曲潇的情诗，内容多是对七年前两人相遇相恋的追思。]],["id"]=[[rlt_dr3text17]]},["rlt_dr3text18"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL双鹤弟子：哼，走着瞧。]],["id"]=[[rlt_dr3text18]]},["rlt_dr3text19"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL双鹤弟子：我师父的寝卧岂容你一个外人随意进出，我瞧你鬼鬼祟祟，不像个好人！]],["id"]=[[rlt_dr3text19]]},["rlt_dr3text20"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL叶轻语：看来这就是林豪鹤“病重”六年的原因，我只怕在双鹤庄不止他一人如此，事关重大，我需传信上报，七日后，你自去青城山的小桥见庞大哥。]],["id"]=[[rlt_dr3text20]]},["rlt_dr3text21"]={["arg1"]=[[文本输出]],["arg2"]=[[泉水茶香气怡人，虽是游客常喝的粗茶，倒也格外甘甜解渴。]],["id"]=[[rlt_dr3text21]]},["rlt_dr3text22"]={["arg1"]=[[文本输出]],["arg2"]=[[你拉开条椅入坐，叶轻语提起桌上的茶壶为你烫杯倒茶。]],["id"]=[[rlt_dr3text22]]},["rlt_dr3text23"]={["arg1"]=[[文本输出]],["arg2"]=[[这时一位双鹤弟子脚步踉跄地跑来，匍匐跪地：不好了，师父他，他在华山小筑被人谋害了，呜……]],["id"]=[[rlt_dr3text23]]},["rlt_dr3text24"]={["arg1"]=[[文本输出]],["arg2"]=[[走到此处，周围不少人歇脚纳凉，热闹得紧。]],["id"]=[[rlt_dr3text24]]},["rlt_dr3text25"]={["arg1"]=[[文本输出]],["arg2"]=[[一位双鹤弟子脚步踉跄地跑来，匍匐跪地：不好了，师父他，他在华山小筑被人谋害了，呜……
如一石激起千层浪，江文鹤等人皆惊慌地赶往华山小筑。]],["id"]=[[rlt_dr3text25]]},["rlt_dr3text26"]={["arg1"]=[[文本输出]],["arg2"]=[[江文鹤捂住不断涌出鲜血的伤口，他脸上表情似惊似恨，双眼盯着你再不曾闭上。]],["id"]=[[rlt_dr3text26]]},["rlt_dr3text27"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL天枢：呵，这趟任务倒比我预料中的轻松，这个送你当见面礼，期待你日后能给我更多的惊喜。NOR
余音未了，天枢与星面者已飞身离去，令牌被他掌风送落至你面前。]],["id"]=[[rlt_dr3text27]]},["rlt_dr3text28"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL樊晗：我不想去镇岳宫看劳什子传刀大会，季师弟如今春风得意，谁还会在意我这个大师兄，你走吧，别扰我清净。NOR
樊晗说完，轻身跃上华山松。]],["id"]=[[rlt_dr3text28]]},["rlt_dr3text29"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL双鹤弟子：少侠此举，难不成与凶手同为一伙？]],["id"]=[[rlt_dr3text29]]},["rlt_dr3text30"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL双鹤弟子：强闯者，死！]],["id"]=[[rlt_dr3text30]]},["rlt_dr3text31"]={["arg1"]=[[文本输出]],["arg2"]=[[你刨开土堆，发现一瓶鹤顶红。]],["id"]=[[rlt_dr3text31]]},["rlt_dr3textout01"]={["arg1"]=[[弹出文本]],["arg2"]=[[樊晗挡住你的前路。]],["id"]=[[rlt_dr3textout01]]},["rlt_dr3textout02"]={["arg1"]=[[弹出文本]],["arg2"]=[[双鹤弟子对你怒目而视。]],["id"]=[[rlt_dr3textout02]]},["rlt_dr3textout03"]={["arg1"]=[[弹出文本]],["arg2"]=[[双鹤弟子拦住了你。]],["id"]=[[rlt_dr3textout03]]},["rlt_dr3textout04"]={["arg1"]=[[弹出文本]],["arg2"]=[[叶轻语喊住了你。]],["id"]=[[rlt_dr3textout04]]},["rlt_dr3textout05"]={["arg1"]=[[弹出文本]],["arg2"]=[[天枢阻止你带江文鹤离开。]],["id"]=[[rlt_dr3textout05]]},["rlt_dr3textout06"]={["arg1"]=[[弹出文本]],["arg2"]=[[你的背包已装不下了。]],["id"]=[[rlt_dr3textout06]]},["rlt_exp1"]={["arg1"]=[[玩家属性变化]],["arg2"]=[[exp]],["arg3"]=550,["countLimit"]=5,["id"]=[[rlt_exp1]],["level"]=250},["rlt_exp2"]={["arg1"]=[[玩家属性变化]],["arg2"]=[[exp]],["arg3"]=650,["countLimit"]=5,["id"]=[[rlt_exp2]],["level"]=250},["rlt_exp700"]={["arg1"]=[[玩家属性变化]],["arg2"]=[[exp]],["arg3"]=4000,["id"]=[[rlt_exp700]]},["rlt_exp800"]={["arg1"]=[[玩家属性变化]],["arg2"]=[[exp]],["arg3"]=19000,["id"]=[[rlt_exp800]]},["rlt_exp801"]={["arg1"]=[[玩家属性变化]],["arg2"]=[[exp]],["arg3"]=14000,["id"]=[[rlt_exp801]]},["rlt_fb18bw"]={["arg1"]=[[弹出文本窗口]],["arg2"]=[[HIW祭文]],["arg3"]=[[HIW;;HIW　　　　　　　　　　　　　　　　　戊戌之年，桂满琼芳，鹤泣西归，哀江湖之不幸，祭于侠者金氏曰：;HIW江湖笔录书未尽，洛阳有纸墨已干。此去千载念悠悠，酆府恩怨何人书？惟留：
