]={["arg1"]=[[可传承玩家标记设置]],["arg2"]=[[轩辕夏已死]],["arg3"]=1,["id"]=[[rlt_sbnpcbj6]]},["rlt_sbnpcbj7"]={["arg1"]=[[可传承玩家标记设置]],["arg2"]=[[送密令]],["arg3"]=1,["id"]=[[rlt_sbnpcbj7]]},["rlt_sbtext1"]={["arg1"]=[[文本输出]],["arg2"]=[[这具尸体面色铁青，眼圈乌黑，身上只有一处极小的伤口，似乎是中毒而死。]],["id"]=[[rlt_sbtext1]]},["rlt_sbtext2"]={["arg1"]=[[副本故事]],["arg2"]=[[CYN欧冶子:误会。老夫名叫欧冶子，此次是来给沐清风贺寿的，没想到他竟然平白遭人毒手。我看方才少侠武功路数似出自唐门，对他们遇害之事可有眉目？;唐元枫:是晚辈鲁莽，抱歉。我爹说沐前辈可能已经遇害，这才差我前来，没想到…唉，我唐门也牵涉其中，若是两位能施以援手，自当感激不尽。]],["arg3"]=3,["id"]=[[rlt_sbtext2]]},["rlt_sbtext3"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL唐元枫：少侠若是有意，可持令来唐门寻我。]],["id"]=[[rlt_sbtext3]]},["rlt_sbtext4"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL唐元枫：若少侠有意相助，便拿着这枚唐门密令来唐门禁地找我便可，大恩大德，感激不尽。;CYN你正打算离开，却觉得有人在暗中窥伺，忙回头时，只觉得青衣一闪，再看时已经消失不见。]],["arg3"]=1,["id"]=[[rlt_sbtext4]]},["rlt_sbtextout1"]={["arg1"]=[[弹出文本]],["arg2"]=[[唐元枫拦住了你。]],["id"]=[[rlt_sbtextout1]]},["rlt_skill1"]={["arg1"]=[[玩家武功经验变化]],["arg2"]=[[jibenneigong]],["arg3"]=100,["id"]=[[rlt_skill1]]},["rlt_skill6"]={["arg1"]=[[玩家武功经验变化]],["arg2"]=[[kuangfengkuaijian]],["arg3"]=1,["id"]=[[rlt_skill6]]},["rlt_skilltext1801"]={["arg1"]=[[弹出文本]],["arg2"]=[=[也许是缺乏实战经验，你对[基本内功]的心法总是无法领会。]=],["id"]=[[rlt_skilltext1801]]},["rlt_stop"]={["arg1"]=[[阻止玩家移动]],["id"]=[[rlt_stop]]},["rlt_stopjishiqi1500"]={["arg1"]=[[停止计时器]],["arg2"]=[[jishiqi1500]],["id"]=[[rlt_stopjishiqi1500]]},["rlt_stopjishiqi1501"]={["arg1"]=[[停止计时器]],["arg2"]=[[jishiqi1501]],["id"]=[[rlt_stopjishiqi1501]]},["rlt_stopjishiqi1502"]={["arg1"]=[[停止计时器]],["arg2"]=[[jishiqi1502]],["id"]=[[rlt_stopjishiqi1502]]},["rlt_stopjishiqi1503"]={["arg1"]=[[停止计时器]],["arg2"]=[[jishiqi1503]],["id"]=[[rlt_stopjishiqi1503]]},["rlt_suiji1500"]={["arg1"]=[[随机结果]],["arg2"]=[[jieguo1500;jieguo1501;jieguo1502;jieguo1503]],["arg3"]=[[1;1;1;1]],["id"]=[[rlt_suiji1500]]},["rlt_text1"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL劳德诺：可恶！
